const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Lake Menindee geometry
  const lakeMenindee = ee.Geometry.Point([142.39, -32.40]).buffer(15000);

  // Define time periods
  const date1Start = '2019-01-15';
  const date1End = '2019-02-15';
  const date2Start = '2021-04-15';
  const date2End = '2021-05-30';

  // Function to calculate water area from Sentinel-2
  function getWaterArea(startDate, endDate, label) {
    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(lakeMenindee)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 40));

    let size = col.size().getInfo();

    if (size === 0) {
      // Fallback to Landsat 8
      col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(lakeMenindee)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUD_COVER', 40));
      size = col.size().getInfo();

      if (size === 0) {
        console.log(`${label}: No images found`);
        return null;
      }
      console.log(`${label}: ${size} Landsat images found`);

      // Calculate NDWI for Landsat (B5=NIR, B6=SWIR)
      col = col.map(img => {
        const ndwi = img.normalizedDifference(['B5', 'B6']).rename('NDWI');
        return ndwi;
      });
    } else {
      console.log(`${label}: ${size} Sentinel-2 images found`);

      // Calculate NDWI for Sentinel-2 (B8=NIR, B11=SWIR)
      col = col.map(img => {
        const ndwi = img.normalizedDifference(['B8', 'B11']).rename('NDWI');
        return ndwi;
      });
    }

    // Composite and threshold water
    const composite = col.median();
    const water = composite.gte(0.3).rename('water');

    // Count water pixels
    const pixelCount = water.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeMenindee,
      scale: 30,
      maxPixels: 1e9
    }).get('water').getInfo();

    // Calculate area in km²
    const area = pixelCount * 0.0009; // 30m pixels = 0.0009 km²

    console.log(`${label} - Water pixels: ${pixelCount}, Area: ${area.toFixed(2)} km²`);
    return area;
  }

  // Get water areas for both dates
  const area2019 = getWaterArea(date1Start, date1End, '2019-02');
  const area2021 = getWaterArea(date2Start, date2End, '2021-05');

  // Validation and answer
  if (area2019 === null || area2021 === null) {
    console.log('<answer>C1</answer>');
    return;
  }

  if (isNaN(area2019) || isNaN(area2021) || area2019 < 0 || area2021 < 0) {
    console.log('<answer>C3</answer>');
    return;
  }

  const change = area2019 - area2021;
  console.log(`\nArea change: ${change.toFixed(2)} km² (2019: ${area2019.toFixed(2)} → 2021: ${area2021.toFixed(2)})`);

  if (change > 0.5) { // shrinkage threshold
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
